{"command": "python3 << 'PYEOF'
import re

with open("/workdir/data/book_prices.json") as f:
    content = f.read()

objects = re.findall(r'\{[^{}]*\}', content, re.DOTALL)
for obj in objects[:30]:
    # Handle mixed quoting: "title": 'value' or "title": "value"
    title_match = re.search(r'"title"\s*:\s*["\']([^"\']*)["\']', obj)
    if title_match:
        print(f"Title: {title_match.group(1)}")
    else:
        print(f"NO MATCH: {obj[:100]}")
